<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_login();$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);
$q=trim((string)($_GET['q']??''));$all=(string)($_GET['all']??'0')==='1';$ids=visible_department_ids($db,$user);
$where=[];$types='';$params=[];if(!$all)$where[]="d.estatus='ACTIVO'";if(!user_is_global($user)){$where[]='d.departamento_id IN ('.($ids?implode(',',array_map('intval',$ids)):'0').')';}if($q!==''){$where[]="(d.nombre LIKE CONCAT('%',?,'%') OR d.codigo LIKE CONCAT('%',?,'%'))";$types.='ss';$params[]=$q;$params[]=$q;}
$sql="SELECT d.*, (SELECT COUNT(DISTINCT ud.usuario_id) FROM usuario_departamento ud WHERE ud.departamento_id=d.departamento_id AND ud.estatus='ACTIVO') usuarios_count FROM departamento d".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY d.es_tesoreria DESC,d.nombre";
$st=$db->prepare($sql);if($types)$st->bind_param($types,...$params);$st->execute();$rs=$st->get_result();$data=[];while($r=$rs->fetch_assoc()){$r['departamento_id']=(int)$r['departamento_id'];$r['es_tesoreria']=(int)$r['es_tesoreria'];$r['usuarios_count']=(int)$r['usuarios_count'];$data[]=$r;}$st->close();$db->close();json_response(['ok'=>true,'data'=>$data]);
